import type { HouseholdEntity, HouseholdOptions, ToggleInput } from "./household-types";
import { Alert, Badge, Button, Card, Group, SimpleGrid, Stack, Text } from "@mantine/core";
import { useWidgetAction, useWidgetCapabilities, useWidgetHost, useWidgetOptions, useWidgetQuery, useWidgetServices } from "@homarr/widget-sdk";
export default function Household() {
  const host = useWidgetHost();
  const options = useWidgetOptions<HouseholdOptions>();
  const services = useWidgetServices();
  const query = useWidgetQuery<HouseholdEntity[]>("states", {}, {refetchInterval: 10000});
  const action = useWidgetAction<unknown, ToggleInput>("toggle");
  const capabilities = useWidgetCapabilities();
  const error = query.error ?? action.error;
  const entities = Array.isArray(options.entities) ? options.entities : [];
  const rows = (query.data ?? []).filter((row) => entities.includes(row.entity_id));
  const toggle = async (row: HouseholdEntity) => { if (!await services.confirm({title:row.attributes.friendly_name ?? row.entity_id, message:`Toggle ${row.entity_id}?`})) return; await action.mutateAsync({entityId:row.entity_id}).catch(() => undefined); };
  return <Stack p="md" h="100%" style={{overflow:"auto"}}><Text fw={600}>{options.title}</Text>
    {error && <Alert color="red">{error.message}<Button size="xs" variant="subtle" onClick={() => void query.refetch()}>Retry</Button></Alert>}
    <SimpleGrid cols={Math.max(1,Math.floor(host.visibleWidth / 180))}>{rows.map((row) => <Card key={row.entity_id} withBorder><Stack gap="xs"><Text fw={500}>{row.attributes.friendly_name ?? row.entity_id}</Text><Group justify="space-between"><Badge color={row.state === "on" ? "teal" : "gray"}>{row.state}</Badge><Button title={capabilities.canRun("toggle", {entityId:row.entity_id}) ? undefined : "Your dashboard permissions do not allow this control"} size="compact-xs" disabled={!capabilities.canRun("toggle", {entityId:row.entity_id}) || action.isPending || !["on","off"].includes(row.state)} onClick={() => void toggle(row)}>Toggle</Button></Group>{host.displayMode === "advanced" && <Text size="xs" c="dimmed">Changed {new Date(row.last_changed).toLocaleString(host.locale)}</Text>}</Stack></Card>)}</SimpleGrid>
    {!entities.length && <Text c="dimmed">Choose your lights and switches in the configuration preview.</Text>}
  </Stack>;
}

