import type { WidgetServerContext } from "@homarr/widget-sdk/server";
import type { HouseholdEntity, HouseholdOptions, ToggleInput } from "./household-types";
import { defineWidgetServer, fetchWidgetConnection, getWidgetServerContext } from "@homarr/widget-sdk/server";
const states = async (context: WidgetServerContext) => { const result = await fetchWidgetConnection<HouseholdEntity[]>(context, {connection:"homeassistant",path:"/api/states"}); if (!result.ok) throw new Error(`Home Assistant returned HTTP ${result.status}`); return result.data; };
export default defineWidgetServer({
  states: (_input: unknown, context) => states(context),
  toggle: async (input: ToggleInput, context) => {
    const {options} = await getWidgetServerContext<HouseholdOptions>(context);
    if (!Array.isArray(options.entities) || !options.entities.includes(input?.entityId)) throw new Error("Choose this entity in the widget configuration first");
    const domain = input.entityId.split(".")[0] ?? "";
    if (!["light","switch","input_boolean","fan"].includes(domain)) throw new Error("This entity does not support the toggle operation");
    const result = await fetchWidgetConnection(context, {connection:"homeassistant",path:`/api/services/${domain}/toggle`,method:"POST",body:{entity_id:input.entityId}});
    if (!result.ok) throw new Error(`Home Assistant returned HTTP ${result.status}`);
    return result.data;
  },
});

