import type { HouseholdEntity, HouseholdOptions } from "./household-types";
import { Alert, Button, MultiSelect, Stack, TextInput } from "@mantine/core";
import { useWidgetOptions, useWidgetQuery, useWidgetServices, useWidgetState } from "@homarr/widget-sdk";
export default function Configuration() {
  const options = useWidgetOptions<HouseholdOptions>();
  const services = useWidgetServices();
  const [title, setTitle] = useWidgetState("configuration-title", options.title);
  const [entities, setEntities] = useWidgetState("configuration-entities", options.entities);
  const [error, setError] = useWidgetState("configuration-error", "");
  const query = useWidgetQuery<HouseholdEntity[]>("states");
  const choices = (query.data ?? []).filter((row) => /^(light|switch|input_boolean|fan)\./.test(row.entity_id)).map((row) => ({value:row.entity_id,label:row.attributes.friendly_name ?? row.entity_id}));
  const save = async () => { try { await services.updateOptions({...options,title,entities}); setError(""); } catch (error) { setError(error instanceof Error ? error.message : String(error)); } };
  return <Stack p="md">{query.error && <Alert color="red">{query.error.message}</Alert>}{error && <Alert color="red">{error}</Alert>}<TextInput label="Panel title" value={title} onChange={(event) => setTitle(event.currentTarget.value)} /><MultiSelect label="Lights and switches" searchable data={choices} value={entities} onChange={setEntities} /><Button onClick={() => void save()}>Use these options</Button></Stack>;
}

